inline double kallen(double x,double y,double z){
    return x*x + y*y + z*z - 2*x*y - 2*x*z- 2*y*z;
}


std::complex<double> DT::A1A1HS1Tree(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1); 

    double t = MA1*MA1  + MH*MH - (s+MH*MH-MS1*MS1)/2. + cos_t/(2.*s) * sqrt(kallen(s,MA1*MA1,MA1*MA1)*kallen(s,MH*MH,MS1*MS1));
	double u = -s - t + MA1*MA1 + MA1*MA1 + MH*MH + MS1*MS1;

	


    return ((4.*cos(alpha)*(MHSqcomp)*(s + (MHSqcomp) + (MS1Sqcomp))*(sin(alpha)*sin(alpha)*sin(alpha)))/(-s + (MHSqcomp)) + (4.*(MS1Sqcomp)*(s + (MHSqcomp) + (MS1Sqcomp))*(cos(alpha)*cos(alpha)*cos(alpha))*sin(alpha))/(-s + (MS1Sqcomp)) + sin(2*alpha)*(2.*(MHSqcomp)*(MS1Sqcomp)*(1/(-t + (MA1*MA1)) + 1./(-u + (MA1*MA1))) + (s*svev*((MHSqcomp) - (MS1Sqcomp))*(s + (MHSqcomp) + (MS1Sqcomp))*sin(2*alpha))/(vev*(-s + (MHSqcomp))*(-s + (MS1Sqcomp)))))/(4.*(svev*svev));
}
inline std::complex<double>
operator+(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) + rhs;
}
   template <typename T>
std::complex<T> operator*(int lhs, const std::complex<T>& rhs) {
   return static_cast<T>(lhs) * rhs;
}

 inline std::complex<double>
operator/(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) / rhs;
}

inline std::complex<double>
operator/(double lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(lhs, 0.0) / rhs;
}

inline double Csc(double x) {
return 1.0 / sin(x);
}

inline double Sec(double x) {
return 1.0 / cos(x);
}

inline double Cot(double x) {
return std::tan(M_PI_2 - x);
}

